   if(c.dash&&dashLearned&&!SwordAway()&&clock>=dashReady&&clock-castAt>=.57f){if(c.move!=0)facing=(int)c.move;dashVY=player.VY;dashUntil=clock+settings.dashDuration;dashReady=clock+settings.dashCooldown;attackAt=-100;audio.Play("dash");fx.Burst(player.X,player.CenterY,9,Color.cyan,clock);}
   if(clock<dashUntil){player.body.gravityScale=0;player.VX=facing*settings.dashSpeed;player.VY=0;}else{if(player.body.gravityScale==0){player.body.gravityScale=1;player.VY=dashVY;}bool busy=clock-attackAt<.39f||clock-castAt<.57f;if(c.move!=0&&!busy)facing=(int)c.move;if(clock>=hurtUntil)player.VX=c.move*settings.moveSpeed*(busy?.42f:1);}
   bool free=!SwordAway()&&clock-attackAt>=.39f&&clock-castAt>=.57f&&clock>=dashUntil&&clock>=hurtUntil;
   if(c.ranged&&free&&clock>=rangedReady){castAt=clock;castFired=false;attackFacing=facing;rangedReady=clock+settings.rangedCooldown*Cooldown;}else if(c.attack&&free){attackAt=clock;attackFacing=facing;meleeHits.Clear();if(run!=null)run.melees++;}
