  public void BeginWave(){if(run==null)return;run.wave++;ClearCombat();foreach(var enemy in enemies)enemy.Destroy();enemies.Clear();if(boss!=null){boss.Destroy();boss=null;}if(worldRoot==null||room!=4){EnterRoom(4,170,620);}else{foreach(var p in platforms){p.broken=false;p.collider.enabled=true;p.Visible(true);}player.Place(170,620);attackAt=castAt=-100;dashUntil=hurtUntil=0;}
   phase=GamePhase.Play;var spec=Rules.Wave(run.wave);if(spec.boss!=null){SpawnBoss(spec.boss,1000);boss.hp=boss.maxHp=Mathf.Round((spec.boss=="master"?150:120)*spec.bossScale);boss.active=true;ChangeBoss("recover",2.2f);player.Place(500,620);cameraLeft=360;}else for(int i=0;i<spec.count;i++){SpawnEnemy(new EnemyData{kind=i%3==2?"moth":"crawler",x=570+i%5*255,y=i%3==2?370+i%2*55:560,min=70,max=1930});enemies[enemies.Count-1].hp=enemies[enemies.Count-1].maxHp=Mathf.Ceil((i%3==2?3:4)*spec.hpScale);}
