  public void FinishWave(){if(run==null||phase!=GamePhase.Play)return;run.cleared=run.wave;run.best=Mathf.Max(run.best,run.wave);PlayerPrefs.SetInt("WuxiaEndlessBest",run.best);hp=Mathf.Min(MaxHP,hp+run.Level("lotus")*.6f);rewardRemaining=rewardTotal=Rules.Wave(run.wave).boss!=null?2:1;phase=GamePhase.WaveClear;restUntil=clock+settings.clearRestDuration;ClearCombat();audio.Boss(false);Notice("此波已破 · 调息片刻",4.5f);}
  public void ShowCards(){phase=GamePhase.Rest;offers=Rules.Offers(data,run,random);pendingUpgrade=null;ui.ShowCards();}
  public void ChooseCard(string id){if(phase!=GamePhase.Rest||Array.IndexOf(offers,id)<0)return;pendingUpgrade=id;ui.UpdateSelection();}
  public void ConfirmCard(){if(phase!=GamePhase.Rest||pendingUpgrade==null)return;string id=pendingUpgrade;pendingUpgrade=null;hp=Rules.Apply(data,run,id,hp);audio.Play("heal");rewardRemaining--;if(rewardRemaining>0)ShowCards();else BeginWave();}
  public void FinishUnlock(){dashLearned=formationLearned=true;rangedReady=formationReady=clock;hp=5;checkpointRoom=2;checkpointX=data.shrineX-160;checkpointFeet=620;phase=GamePhase.Play;ui.HideModal();Notice("已悟踏云诀与万剑归宗 · 御剑越崖",3);}
  void Interactions(bool press){if(room==1&&!healTaken&&Mathf.Abs(player.X-data.healX)<50&&Mathf.Abs(player.CenterY-315)<65){healTaken=true;hp=MaxHP;healPickup?.Visible(false);audio.Play("heal");Notice("归元草 · 气血已满",2);}string text="";Action action=null;if(room==2&&!dashLearned&&Mathf.Abs(player.X-data.shrineX)<100){text="E 参悟剑诀";action=()=>{phase=GamePhase.Unlock;audio.Play("heal");ui.ShowUnlock();};}else if(room==3&&stoneDefeated&&player.X>1650){text="E 开启禁庭";action=()=>EnterRoom(4,150,620);}else if(room==4&&masterDefeated&&player.X>1080){text="E 完成归元封印";action=()=>{phase=GamePhase.Won;ui.ShowWon();};}else foreach(var exit in data.rooms[room].exits){if(Mathf.Abs(player.X-exit.x)>80)continue;text=exit.requiresDash&&!dashLearned?"需踏云诀":"E "+exit.label;if(!exit.requiresDash||dashLearned)action=()=>EnterRoom(exit.to,exit.spawnX,exit.spawnY+29);break;}
   ui.SetPrompt(text);if(press)action?.Invoke();}
  public void Notice(string text,float duration=2){notice=text;noticeUntil=clock+duration;}
  void RefreshHerbs(){foreach(var h in herbs)h.Visible(SheltersVisible);}
  public bool Sheltered(){if(!SheltersVisible||player.Feet<560)return false;foreach(float x in ShelterXs)if(Mathf.Abs(player.X-x)<=82)return true;return false;}
  void UpdateCamera(float dt,float renderX=float.NaN){float px=float.IsNaN(renderX)?player.X:renderX;float target=endless&&boss!=null?360:Mathf.Clamp(px-500,0,Mathf.Max(0,Width-1280));cameraLeft=Mathf.Lerp(cameraLeft,target,1-Mathf.Exp(-dt*8));var pos=new Vector3((cameraLeft+640)/100,3.6f,-10);if(clock<shakeUntil){pos.x+=Mathf.Sin(clock*127)*shakePower/100;pos.y+=Mathf.Cos(clock*111)*shakePower/100;}gameCamera.transform.position=pos;if(background!=null)background.root.transform.position=PixelWorld.Position(cameraLeft+640,360);}
  public void Shake(float strength,float duration){shakePower=strength;shakeUntil=clock+duration;}
  void ClearLevel(){ClearCombat();fx?.Clear();if(player!=null)player.Disable();foreach(var e in enemies)e.Disable();boss?.Disable();if(worldRoot){art.ForgetWorld(worldRoot);worldRoot.gameObject.SetActive(false);NativeObject.Remove(worldRoot.gameObject);}else if(background!=null)background.Destroy();worldRoot=null;player=boss=null;enemies.Clear();platforms.Clear();herbs.Clear();background=sword=swordBehind=sleeve=meleeArc=healPickup=null;}
  void OnDestroy(){if(!Initialized)return;fx.Dispose();art.Dispose();Physics2D.simulationMode=SimulationMode2D.FixedUpdate;}
